import {
	AdminApp,
	AdminBootError,
	type AdminBootErrorLabels,
	type AdminBranding,
	type PluginAdmins,
	type RoutePrefetchFiles,
} from "@emdash-cms/admin/app";
import type { Messages } from "@lingui/core";
import { useEffect, useState } from "react";
// @ts-ignore - virtual module generated by integration
import { loadPluginAdmins } from "virtual:emdash/admin-loader";
// @ts-ignore - virtual module generated by integration
import { authProviders } from "virtual:emdash/auth-providers";

interface AdminWrapperProps {
	locale: string;
	/** URL of the compiled Lingui catalog for `locale`, preloaded by `admin.astro`. */
	messagesUrl: string;
	/** Configured admin white-label branding (logo, site name), read server-side from `admin.astro`. */
	adminBranding?: AdminBranding;
	/** Shown if the catalog or plugin admins fail to load, in the request's language. */
	bootErrorLabels: AdminBootErrorLabels;
	routePrefetchFiles: RoutePrefetchFiles;
}

interface AdminBoot {
	pluginAdmins: PluginAdmins;
	messages: Messages;
}

type BootState =
	| { status: "loading" }
	| { status: "ready"; boot: AdminBoot }
	| { status: "failed"; retrying: boolean };

const boots = new Map<string, Promise<AdminBoot>>();

async function importMessages(url: string): Promise<Messages> {
	const catalog: { messages: Messages } = await import(/* @vite-ignore */ url);
	return catalog.messages;
}

function loadAdminBoot(messagesUrl: string): Promise<AdminBoot> {
	let boot = boots.get(messagesUrl);
	if (!boot) {
		boot = Promise.all([loadPluginAdmins(), importMessages(messagesUrl)]).then(
			([{ pluginAdmins }, messages]) => ({ pluginAdmins, messages }),
		);
		// The component handles a failure once its effect runs, which can be after the rejection.
		boot.catch(() => {});
		boots.set(messagesUrl, boot);
	}
	return boot;
}

// No Suspense boundary here: React holds back revealing a boundary's content
// until 300 ms after its fallback committed, which would delay every admin load.
export default function AdminWrapper({
	locale,
	messagesUrl,
	adminBranding,
	bootErrorLabels,
	routePrefetchFiles,
}: AdminWrapperProps) {
	const pending = loadAdminBoot(messagesUrl);
	const [state, setState] = useState<BootState>({ status: "loading" });

	useEffect(() => {
		let active = true;
		void (async () => {
			let next: BootState;
			try {
				next = { status: "ready", boot: await pending };
			} catch (error) {
				console.error("[emdash] The admin failed to load:", error);
				next = { status: "failed", retrying: false };
			}
			if (active) setState(next);
		})();
		return () => {
			active = false;
		};
	}, [pending]);

	if (state.status === "failed") {
		return (
			<AdminBootError
				labels={bootErrorLabels}
				retrying={state.retrying}
				onRetry={() => {
					boots.delete(messagesUrl);
					setState({ status: "failed", retrying: true });
				}}
			/>
		);
	}
	if (state.status === "loading") return null;

	return (
		<AdminApp
			pluginAdmins={state.boot.pluginAdmins}
			authProviders={authProviders}
			adminBranding={adminBranding}
			locale={locale}
			messages={state.boot.messages}
			routePrefetchFiles={routePrefetchFiles}
		/>
	);
}
